#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 10

static int parent[MAXN];
static int rank_arr[MAXN];

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        if (rank_arr[a] < rank_arr[b])
            parent[a] = b;
        else if (rank_arr[a] > rank_arr[b])
            parent[b] = a;
        else {
            parent[b] = a;
            rank_arr[a]++;
        }
    }
}

int main(int argc, char **argv) {
    // initialise disjoint set for elements 0..9
    for (int i = 0; i < MAXN; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int idx = 1; // current argument index
    while (idx < argc) {
        char *cmd = argv[idx++];
        if (strcmp(cmd, "UNION") == 0) {
            if (idx + 1 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[idx], NULL, 10);
            long b = strtol(argv[idx+1], NULL, 10);
            idx += 2;
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) { puts("INVALID"); continue; }
            union_sets((int)a, (int)b);
            printf("UNION %ld %ld\n", a, b);
        } else if (strcmp(cmd, "FIND") == 0) {
            if (idx >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[idx], NULL, 10);
            idx++;
            if (a < 0 || a >= MAXN) { puts("INVALID"); continue; }
            int root = find_set((int)a);
            printf("FIND %ld=%d\n", a, root);
        } else if (strcmp(cmd, "CHECK") == 0) {
            if (idx + 1 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[idx], NULL, 10);
            long b = strtol(argv[idx+1], NULL, 10);
            idx += 2;
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) { puts("INVALID"); continue; }
            if (find_set((int)a) == find_set((int)b))
                puts("YES");
            else
                puts("NO");
        } else {
            puts("INVALID");
        }
    }
    return 0;
}
